cases.setup_script:
export PYTHONDONTWRITEBYTECODE=1 H=/opt/bashos-parity/harness/helpers/system-seccomp.py
out=$(/usr/bin/python3 "$H" --errno uname:EFAULT -- /usr/bin/uname -s 2>&1) && { echo "CONTROL-FAILED uname rule not applied"; exit 98; }
[[ $out == *"Bad address"* ]] || { echo "CONTROL-FAILED unexpected control diagnostic"; exit 98; }
